import {soundscape as audio,tracks} from './soundscape.js';
const quick=document.createElement('button');quick.type='button';quick.className='arena-music';document.querySelector('.arena').append(quick);quick.onclick=()=>{audio.unlock();audio.setMusic(audio.musicMuted)};
const button=document.getElementById('sound');function paint(){button.innerHTML=audio.enabled?'SOM ON <span>◉</span>':'SOM OFF <span>◌</span>';button.setAttribute('aria-pressed',audio.enabled);quick.textContent=audio.musicMuted?'♫ MÚSICA OFF':'♫ MÚSICA ON';quick.setAttribute('aria-label',audio.musicMuted?'Ativar música':'Mutar música');quick.setAttribute('aria-pressed',String(audio.musicMuted));document.getElementById('music-toggle')?.toggleAttribute('checked',audio.musicOn);const checkbox=document.getElementById('music-toggle');if(checkbox)checkbox.checked=audio.musicOn}
button.onclick=()=>{audio.enabled=!audio.enabled;audio.unlock();audio.apply();paint()};window.addEventListener('brasa-audio-change',paint);paint();
const panel=document.createElement('details');panel.className='audio-panel';panel.innerHTML=`<summary>♫ TRILHA & EFEITOS <span>HINOS INSTRUMENTAIS · RITMO ARCADE</span></summary><div class="audio-options"><label>TRILHA<select id="music-track">${tracks.map((t,i)=>`<option value="${i}" ${audio.track===i?'selected':''}>${t.name}</option>`).join('')}</select></label><label>VOLUME DA MÚSICA<input id="music-volume" type="range" min="0" max="50" value="${Math.round(audio.musicVolume*100)}"></label><label>VOLUME DOS EFEITOS<input id="fx-volume" type="range" min="0" max="100" value="${Math.round(audio.fxVolume*100)}"></label><label>VELOCIDADE<select id="music-tempo">${[1,1.1,1.18,1.25].map(n=>`<option value="${n}" ${n===audio.tempo?'selected':''}>${n===1?'Original':Math.round((n-1)*100)+'% mais rápida'}</option>`).join('')}</select></label><label class="audio-check"><input id="music-toggle" type="checkbox" ${audio.musicOn?'checked':''}> MÚSICA</label><label class="audio-check"><input id="fx-toggle" type="checkbox" ${audio.fxOn?'checked':''}> EFEITOS</label></div><p>Sem voz. A velocidade muda mantendo o tom da gravação. <a href="music-credits.html" target="_blank" rel="noopener">Fontes e créditos ↗</a></p>`;document.querySelector('.game-shell').after(panel);
document.getElementById('music-track').onchange=e=>{audio.unlock();audio.select(+e.target.value)};document.getElementById('music-tempo').onchange=e=>{audio.tempo=+e.target.value;audio.apply()};document.getElementById('music-volume').oninput=e=>{audio.musicVolume=+e.target.value/100;audio.apply()};document.getElementById('fx-volume').oninput=e=>{audio.fxVolume=+e.target.value/100;audio.apply()};document.getElementById('music-toggle').onchange=e=>{audio.setMusic(e.target.checked)};document.getElementById('fx-toggle').onchange=e=>{audio.fxOn=e.target.checked;audio.apply()};window.addEventListener('brasa-audio-error',()=>{panel.querySelector('p').textContent='Não foi possível carregar a trilha. Os efeitos continuam disponíveis.'});
